  "model_contract_digest" ANY NOT NULL CHECK(typeof("model_contract_digest")='text' AND length(CAST("model_contract_digest" AS BLOB))=length("model_contract_digest") AND length(CAST("model_contract_digest" AS BLOB))=64 AND "model_contract_digest" NOT GLOB '*[^0-9a-f]*'),
  "model_configuration_ref" ANY NOT NULL CHECK(typeof("model_configuration_ref")='text' AND length(CAST("model_configuration_ref" AS BLOB))=length("model_configuration_ref") AND length(CAST("model_configuration_ref" AS BLOB)) BETWEEN 1 AND 96 AND "model_configuration_ref" NOT GLOB '*[^0-9A-Za-z.-]*' AND substr("model_configuration_ref",1,1) GLOB '[0-9A-Za-z]' AND lower("model_configuration_ref") NOT GLOB 'connector-*' AND lower("model_configuration_ref") NOT GLOB 'tunnel-*' AND lower("model_configuration_ref") NOT GLOB 'workspace-*' AND lower("model_configuration_ref") NOT GLOB 'org-*' AND lower("model_configuration_ref") NOT GLOB 'organization-*' AND lower("model_configuration_ref") NOT GLOB 'user-*'),
