  "context_ref" ANY NOT NULL CHECK(typeof("context_ref")='text' AND length(CAST("context_ref" AS BLOB))=length("context_ref") AND length(CAST("context_ref" AS BLOB)) BETWEEN 1 AND 96 AND "context_ref" NOT GLOB '*[^0-9A-Za-z.-]*' AND substr("context_ref",1,1) GLOB '[0-9A-Za-z]' AND lower("context_ref") NOT GLOB 'connector-*' AND lower("context_ref") NOT GLOB 'tunnel-*' AND lower("context_ref") NOT GLOB 'workspace-*' AND lower("context_ref") NOT GLOB 'org-*' AND lower("context_ref") NOT GLOB 'organization-*' AND lower("context_ref") NOT GLOB 'user-*'),
