  "artifact_schema_id" ANY NOT NULL CHECK(typeof("artifact_schema_id")='text' AND length(CAST("artifact_schema_id" AS BLOB))=length("artifact_schema_id") AND "artifact_schema_id" IN ('governed-execution.nwp-pre-execution-plan-artifact.v1','governed-execution.nwp-post-execution-semantic-review-artifact.v1')),
  "artifact_ref" ANY NOT NULL CHECK(typeof("artifact_ref")='text' AND length(CAST("artifact_ref" AS BLOB))=length("artifact_ref") AND length(CAST("artifact_ref" AS BLOB)) BETWEEN 1 AND 96 AND "artifact_ref" NOT GLOB '*[^0-9A-Za-z.-]*' AND substr("artifact_ref",1,1) GLOB '[0-9A-Za-z]' AND lower("artifact_ref") NOT GLOB 'connector-*' AND lower("artifact_ref") NOT GLOB 'tunnel-*' AND lower("artifact_ref") NOT GLOB 'workspace-*' AND lower("artifact_ref") NOT GLOB 'org-*' AND lower("artifact_ref") NOT GLOB 'organization-*' AND lower("artifact_ref") NOT GLOB 'user-*'),
