  "invocation_status" ANY NOT NULL CHECK(typeof("invocation_status")='text' AND length(CAST("invocation_status" AS BLOB))=length("invocation_status") AND "invocation_status"='normalized_typed_proposal_supplied'),
  "source_invocation_started_at" ANY NOT NULL CHECK(typeof("source_invocation_started_at")='text' AND length(CAST("source_invocation_started_at" AS BLOB))=length("source_invocation_started_at") AND length(CAST("source_invocation_started_at" AS BLOB))=20 AND "source_invocation_started_at" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9]Z' AND substr("source_invocation_started_at",1,4) BETWEEN '0001' AND '9999' AND substr("source_invocation_started_at",6,2) BETWEEN '01' AND '12' AND substr("source_invocation_started_at",9,2) BETWEEN '01' AND '31' AND substr("source_invocation_started_at",12,2) BETWEEN '00' AND '23' AND substr("source_invocation_started_at",15,2) BETWEEN '00' AND '59' AND substr("source_invocation_started_at",18,2) BETWEEN '00' AND '59' AND strftime('%Y-%m-%dT%H:%M:%SZ',"source_invocation_started_at") IS NOT NULL AND strftime('%Y-%m-%dT%H:%M:%SZ',"source_invocation_started_at")="source_invocation_started_at"),
  "source_invocation_completed_at" ANY NOT NULL CHECK(typeof("source_invocation_completed_at")='text' AND length(CAST("source_invocation_completed_at" AS BLOB))=length("source_invocation_completed_at") AND length(CAST("source_invocation_completed_at" AS BLOB))=20 AND "source_invocation_completed_at" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9]Z' AND substr("source_invocation_completed_at",1,4) BETWEEN '0001' AND '9999' AND substr("source_invocation_completed_at",6,2) BETWEEN '01' AND '12' AND substr("source_invocation_completed_at",9,2) BETWEEN '01' AND '31' AND substr("source_invocation_completed_at",12,2) BETWEEN '00' AND '23' AND substr("source_invocation_completed_at",15,2) BETWEEN '00' AND '59' AND substr("source_invocation_completed_at",18,2) BETWEEN '00' AND '59' AND strftime('%Y-%m-%dT%H:%M:%SZ',"source_invocation_completed_at") IS NOT NULL AND strftime('%Y-%m-%dT%H:%M:%SZ',"source_invocation_completed_at")="source_invocation_completed_at"),
  "source_invocation_digest" ANY NOT NULL CHECK(typeof("source_invocation_digest")='text' AND length(CAST("source_invocation_digest" AS BLOB))=length("source_invocation_digest") AND length(CAST("source_invocation_digest" AS BLOB))=64 AND "source_invocation_digest" NOT GLOB '*[^0-9a-f]*'),
  CONSTRAINT development_model_source_invocations_phase_algebra CHECK((proposal_phase='pre_execution_plan' AND context_schema_id='governed-execution.nwp-pre-execution-planning-context.v1' AND artifact_schema_id='governed-execution.nwp-pre-execution-plan-artifact.v1') OR (proposal_phase='post_execution_semantic_review' AND context_schema_id='governed-execution.nwp-post-execution-semantic-review-context.v1' AND artifact_schema_id='governed-execution.nwp-post-execution-semantic-review-artifact.v1')),
  PRIMARY KEY(source_invocation_ref),
  UNIQUE(proposal_phase,source_invocation_ref)
) STRICT;

