  FOREIGN KEY(program_ref,delivery_attempt_ref) REFERENCES development_delivery_attempts(program_ref,delivery_attempt_ref) ON UPDATE RESTRICT ON DELETE RESTRICT NOT DEFERRABLE INITIALLY IMMEDIATE,
  FOREIGN KEY(program_ref,authority_evaluation_ref) REFERENCES development_authority_evaluations(program_ref,authority_evaluation_ref) ON UPDATE RESTRICT ON DELETE RESTRICT NOT DEFERRABLE INITIALLY IMMEDIATE
