CREATE TABLE "development_private_proposal_artifact_bindings" (
  "schema_id" ANY NOT NULL CHECK(typeof("schema_id")='text' AND length(CAST("schema_id" AS BLOB))=length("schema_id") AND "schema_id"='governed-execution.nwp-private-proposal-artifact-binding.v1'),
  "artifact_ref" ANY NOT NULL CHECK(typeof("artifact_ref")='text' AND length(CAST("artifact_ref" AS BLOB))=length("artifact_ref") AND length(CAST("artifact_ref" AS BLOB)) BETWEEN 1 AND 96 AND "artifact_ref" NOT GLOB '*[^0-9A-Za-z.-]*' AND substr("artifact_ref",1,1) GLOB '[0-9A-Za-z]' AND lower("artifact_ref") NOT GLOB 'connector-*' AND lower("artifact_ref") NOT GLOB 'tunnel-*' AND lower("artifact_ref") NOT GLOB 'workspace-*' AND lower("artifact_ref") NOT GLOB 'org-*' AND lower("artifact_ref") NOT GLOB 'organization-*' AND lower("artifact_ref") NOT GLOB 'user-*'),
  "proposal_phase" ANY NOT NULL CHECK(typeof("proposal_phase")='text' AND length(CAST("proposal_phase" AS BLOB))=length("proposal_phase") AND "proposal_phase" IN ('pre_execution_plan','post_execution_semantic_review')),
  "artifact_schema_id" ANY NOT NULL CHECK(typeof("artifact_schema_id")='text' AND length(CAST("artifact_schema_id" AS BLOB))=length("artifact_schema_id") AND "artifact_schema_id" IN ('governed-execution.nwp-pre-execution-plan-artifact.v1','governed-execution.nwp-post-execution-semantic-review-artifact.v1')),
  "artifact_digest" ANY NOT NULL CHECK(typeof("artifact_digest")='text' AND length(CAST("artifact_digest" AS BLOB))=length("artifact_digest") AND length(CAST("artifact_digest" AS BLOB))=64 AND "artifact_digest" NOT GLOB '*[^0-9a-f]*'),
  "artifact_canonical_byte_length" ANY NOT NULL CHECK(typeof("artifact_canonical_byte_length")='integer' AND "artifact_canonical_byte_length" BETWEEN 1 AND 65536),
  "safe_projection_schema_id" ANY NOT NULL CHECK(typeof("safe_projection_schema_id")='text' AND length(CAST("safe_projection_schema_id" AS BLOB))=length("safe_projection_schema_id") AND "safe_projection_schema_id" IN ('governed-execution.nwp-pre-execution-plan-safe-projection.v1','governed-execution.nwp-post-execution-semantic-review-safe-projection.v1')),
  "safe_projection_digest" ANY NOT NULL CHECK(typeof("safe_projection_digest")='text' AND length(CAST("safe_projection_digest" AS BLOB))=length("safe_projection_digest") AND length(CAST("safe_projection_digest" AS BLOB))=64 AND "safe_projection_digest" NOT GLOB '*[^0-9a-f]*'),
  "privacy_classification" ANY NOT NULL CHECK(typeof("privacy_classification")='text' AND length(CAST("privacy_classification" AS BLOB))=length("privacy_classification") AND "privacy_classification"='private_normalized_model_proposal'),
  "artifact_validated_at" ANY NOT NULL CHECK(typeof("artifact_validated_at")='text' AND length(CAST("artifact_validated_at" AS BLOB))=length("artifact_validated_at") AND length(CAST("artifact_validated_at" AS BLOB))=20 AND "artifact_validated_at" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9]Z' AND substr("artifact_validated_at",1,4) BETWEEN '0001' AND '9999' AND substr("artifact_validated_at",6,2) BETWEEN '01' AND '12' AND substr("artifact_validated_at",9,2) BETWEEN '01' AND '31' AND substr("artifact_validated_at",12,2) BETWEEN '00' AND '23' AND substr("artifact_validated_at",15,2) BETWEEN '00' AND '59' AND substr("artifact_validated_at",18,2) BETWEEN '00' AND '59' AND strftime('%Y-%m-%dT%H:%M:%SZ',"artifact_validated_at") IS NOT NULL AND strftime('%Y-%m-%dT%H:%M:%SZ',"artifact_validated_at")="artifact_validated_at"),
  "artifact_binding_digest" ANY NOT NULL CHECK(typeof("artifact_binding_digest")='text' AND length(CAST("artifact_binding_digest" AS BLOB))=length("artifact_binding_digest") AND length(CAST("artifact_binding_digest" AS BLOB))=64 AND "artifact_binding_digest" NOT GLOB '*[^0-9a-f]*'),
  CONSTRAINT development_private_proposal_artifact_bindings_phase_algebra CHECK((proposal_phase='pre_execution_plan' AND artifact_schema_id='governed-execution.nwp-pre-execution-plan-artifact.v1' AND safe_projection_schema_id='governed-execution.nwp-pre-execution-plan-safe-projection.v1') OR (proposal_phase='post_execution_semantic_review' AND artifact_schema_id='governed-execution.nwp-post-execution-semantic-review-artifact.v1' AND safe_projection_schema_id='governed-execution.nwp-post-execution-semantic-review-safe-projection.v1')),
  PRIMARY KEY(artifact_ref),
  UNIQUE(proposal_phase,artifact_ref)
) STRICT;

