  "evidence_set_ref" ANY NOT NULL CHECK(typeof("evidence_set_ref")='text' AND length(CAST("evidence_set_ref" AS BLOB))=length("evidence_set_ref") AND length(CAST("evidence_set_ref" AS BLOB)) BETWEEN 1 AND 96 AND "evidence_set_ref" NOT GLOB '*[^0-9A-Za-z.-]*' AND substr("evidence_set_ref",1,1) GLOB '[0-9A-Za-z]' AND lower("evidence_set_ref") NOT GLOB 'connector-*' AND lower("evidence_set_ref") NOT GLOB 'tunnel-*' AND lower("evidence_set_ref") NOT GLOB 'workspace-*' AND lower("evidence_set_ref") NOT GLOB 'org-*' AND lower("evidence_set_ref") NOT GLOB 'organization-*' AND lower("evidence_set_ref") NOT GLOB 'user-*'),
  "evidence_set_digest" ANY NOT NULL CHECK(typeof("evidence_set_digest")='text' AND length(CAST("evidence_set_digest" AS BLOB))=length("evidence_set_digest") AND length(CAST("evidence_set_digest" AS BLOB))=64 AND "evidence_set_digest" NOT GLOB '*[^0-9a-f]*'),
  "proposal_created_at" ANY NOT NULL CHECK(typeof("proposal_created_at")='text' AND length(CAST("proposal_created_at" AS BLOB))=length("proposal_created_at") AND length(CAST("proposal_created_at" AS BLOB))=20 AND "proposal_created_at" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9]Z' AND substr("proposal_created_at",1,4) BETWEEN '0001' AND '9999' AND substr("proposal_created_at",6,2) BETWEEN '01' AND '12' AND substr("proposal_created_at",9,2) BETWEEN '01' AND '31' AND substr("proposal_created_at",12,2) BETWEEN '00' AND '23' AND substr("proposal_created_at",15,2) BETWEEN '00' AND '59' AND substr("proposal_created_at",18,2) BETWEEN '00' AND '59' AND strftime('%Y-%m-%dT%H:%M:%SZ',"proposal_created_at") IS NOT NULL AND strftime('%Y-%m-%dT%H:%M:%SZ',"proposal_created_at")="proposal_created_at"),
  "proposal_digest" ANY NOT NULL CHECK(typeof("proposal_digest")='text' AND length(CAST("proposal_digest" AS BLOB))=length("proposal_digest") AND length(CAST("proposal_digest" AS BLOB))=64 AND "proposal_digest" NOT GLOB '*[^0-9a-f]*'),
  CONSTRAINT development_model_proposals_phase_algebra CHECK((proposal_phase='pre_execution_plan' AND context_schema_id='governed-execution.nwp-pre-execution-planning-context.v1' AND artifact_schema_id='governed-execution.nwp-pre-execution-plan-artifact.v1' AND safe_projection_schema_id='governed-execution.nwp-pre-execution-plan-safe-projection.v1' AND recommendation IN ('select_for_dispatch_gates','defer','block','replan','terminal_reject')) OR (proposal_phase='post_execution_semantic_review' AND context_schema_id='governed-execution.nwp-post-execution-semantic-review-context.v1' AND artifact_schema_id='governed-execution.nwp-post-execution-semantic-review-artifact.v1' AND safe_projection_schema_id='governed-execution.nwp-post-execution-semantic-review-safe-projection.v1' AND recommendation IN ('accept_candidate','repair_candidate','replan','terminal_reject','block'))),
  PRIMARY KEY(proposal_ref),
  UNIQUE(source_invocation_ref),
  UNIQUE(artifact_ref),
  UNIQUE(proposal_phase,proposal_ref),
  FOREIGN KEY(proposal_phase,source_invocation_ref) REFERENCES development_model_source_invocations(proposal_phase,source_invocation_ref) ON UPDATE RESTRICT ON DELETE RESTRICT NOT DEFERRABLE INITIALLY IMMEDIATE,
  FOREIGN KEY(proposal_phase,artifact_ref) REFERENCES development_private_proposal_artifact_bindings(proposal_phase,artifact_ref) ON UPDATE RESTRICT ON DELETE RESTRICT NOT DEFERRABLE INITIALLY IMMEDIATE
) STRICT;

