CREATE TABLE "development_model_proposal_evidence_bindings" (
  "schema_id" ANY NOT NULL CHECK(typeof("schema_id")='text' AND length(CAST("schema_id" AS BLOB))=length("schema_id") AND "schema_id"='governed-execution.nwp-model-proposal-evidence-binding.v1'),
  "proposal_ref" ANY NOT NULL CHECK(typeof("proposal_ref")='text' AND length(CAST("proposal_ref" AS BLOB))=length("proposal_ref") AND length(CAST("proposal_ref" AS BLOB)) BETWEEN 1 AND 96 AND "proposal_ref" NOT GLOB '*[^0-9A-Za-z.-]*' AND substr("proposal_ref",1,1) GLOB '[0-9A-Za-z]' AND lower("proposal_ref") NOT GLOB 'connector-*' AND lower("proposal_ref") NOT GLOB 'tunnel-*' AND lower("proposal_ref") NOT GLOB 'workspace-*' AND lower("proposal_ref") NOT GLOB 'org-*' AND lower("proposal_ref") NOT GLOB 'organization-*' AND lower("proposal_ref") NOT GLOB 'user-*'),
  "proposal_phase" ANY NOT NULL CHECK(typeof("proposal_phase")='text' AND length(CAST("proposal_phase" AS BLOB))=length("proposal_phase") AND "proposal_phase" IN ('pre_execution_plan','post_execution_semantic_review')),
  "evidence_set_ref" ANY NOT NULL CHECK(typeof("evidence_set_ref")='text' AND length(CAST("evidence_set_ref" AS BLOB))=length("evidence_set_ref") AND length(CAST("evidence_set_ref" AS BLOB)) BETWEEN 1 AND 96 AND "evidence_set_ref" NOT GLOB '*[^0-9A-Za-z.-]*' AND substr("evidence_set_ref",1,1) GLOB '[0-9A-Za-z]' AND lower("evidence_set_ref") NOT GLOB 'connector-*' AND lower("evidence_set_ref") NOT GLOB 'tunnel-*' AND lower("evidence_set_ref") NOT GLOB 'workspace-*' AND lower("evidence_set_ref") NOT GLOB 'org-*' AND lower("evidence_set_ref") NOT GLOB 'organization-*' AND lower("evidence_set_ref") NOT GLOB 'user-*'),
  "evidence_role" ANY NOT NULL CHECK(typeof("evidence_role")='text' AND length(CAST("evidence_role" AS BLOB))=length("evidence_role") AND "evidence_role" IN ('standing_policy','risk_lane','repository_binding','base_binding','authorized_path_scope','cost_ceiling','token_ceiling','time_ceiling','delivery_ceiling','effect_ceiling','authority_currentness_attestation','authority_selection_observation','global_stop','validation_requirement','review_requirement','qualified_remote_host_readiness','candidate_capsule','worker_result','validation_result','independent_review')),
  "role_rank" ANY NOT NULL CHECK(typeof("role_rank")='integer' AND "role_rank" BETWEEN 5 AND 19),
  "ordinal" ANY NOT NULL CHECK(typeof("ordinal")='integer' AND "ordinal"=0),
  "evidence_ref" ANY NOT NULL CHECK(typeof("evidence_ref")='text' AND length(CAST("evidence_ref" AS BLOB))=length("evidence_ref") AND length(CAST("evidence_ref" AS BLOB)) BETWEEN 1 AND 96 AND "evidence_ref" NOT GLOB '*[^0-9A-Za-z.-]*' AND substr("evidence_ref",1,1) GLOB '[0-9A-Za-z]' AND lower("evidence_ref") NOT GLOB 'connector-*' AND lower("evidence_ref") NOT GLOB 'tunnel-*' AND lower("evidence_ref") NOT GLOB 'workspace-*' AND lower("evidence_ref") NOT GLOB 'org-*' AND lower("evidence_ref") NOT GLOB 'organization-*' AND lower("evidence_ref") NOT GLOB 'user-*'),
  "evidence_digest" ANY NOT NULL CHECK(typeof("evidence_digest")='text' AND length(CAST("evidence_digest" AS BLOB))=length("evidence_digest") AND length(CAST("evidence_digest" AS BLOB))=64 AND "evidence_digest" NOT GLOB '*[^0-9a-f]*'),
  "required_for_selection" ANY NOT NULL CHECK(typeof("required_for_selection")='integer' AND "required_for_selection" IN (0,1)),
  "evidence_bound_at" ANY NOT NULL CHECK(typeof("evidence_bound_at")='text' AND length(CAST("evidence_bound_at" AS BLOB))=length("evidence_bound_at") AND length(CAST("evidence_bound_at" AS BLOB))=20 AND "evidence_bound_at" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9]Z' AND substr("evidence_bound_at",1,4) BETWEEN '0001' AND '9999' AND substr("evidence_bound_at",6,2) BETWEEN '01' AND '12' AND substr("evidence_bound_at",9,2) BETWEEN '01' AND '31' AND substr("evidence_bound_at",12,2) BETWEEN '00' AND '23' AND substr("evidence_bound_at",15,2) BETWEEN '00' AND '59' AND substr("evidence_bound_at",18,2) BETWEEN '00' AND '59' AND strftime('%Y-%m-%dT%H:%M:%SZ',"evidence_bound_at") IS NOT NULL AND strftime('%Y-%m-%dT%H:%M:%SZ',"evidence_bound_at")="evidence_bound_at"),
  "evidence_binding_digest" ANY NOT NULL CHECK(typeof("evidence_binding_digest")='text' AND length(CAST("evidence_binding_digest" AS BLOB))=length("evidence_binding_digest") AND length(CAST("evidence_binding_digest" AS BLOB))=64 AND "evidence_binding_digest" NOT GLOB '*[^0-9a-f]*'),
  CONSTRAINT development_model_proposal_evidence_bindings_phase_algebra CHECK((proposal_phase='pre_execution_plan' AND ((evidence_role='standing_policy' AND role_rank=5 AND ordinal=0 AND required_for_selection=1) OR (evidence_role='risk_lane' AND role_rank=6 AND ordinal=0 AND required_for_selection=1) OR (evidence_role='repository_binding' AND role_rank=7 AND ordinal=0 AND required_for_selection=1) OR (evidence_role='base_binding' AND role_rank=8 AND ordinal=0 AND required_for_selection=1) OR (evidence_role='authorized_path_scope' AND role_rank=9 AND ordinal=0 AND required_for_selection=1) OR (evidence_role='cost_ceiling' AND role_rank=10 AND ordinal=0 AND required_for_selection=1) OR (evidence_role='token_ceiling' AND role_rank=11 AND ordinal=0 AND required_for_selection=1) OR (evidence_role='time_ceiling' AND role_rank=12 AND ordinal=0 AND required_for_selection=1) OR (evidence_role='delivery_ceiling' AND role_rank=13 AND ordinal=0 AND required_for_selection=1) OR (evidence_role='effect_ceiling' AND role_rank=14 AND ordinal=0 AND required_for_selection=1) OR (evidence_role='authority_selection_observation' AND role_rank=15 AND ordinal=0 AND required_for_selection=1) OR (evidence_role='global_stop' AND role_rank=16 AND ordinal=0 AND required_for_selection=1) OR (evidence_role='validation_requirement' AND role_rank=17 AND ordinal=0 AND required_for_selection=1) OR (evidence_role='review_requirement' AND role_rank=18 AND ordinal=0 AND required_for_selection=1) OR (evidence_role='qualified_remote_host_readiness' AND role_rank=19 AND ordinal=0 AND required_for_selection=0))) OR (proposal_phase='post_execution_semantic_review' AND ((evidence_role='candidate_capsule' AND role_rank=5 AND ordinal=0 AND required_for_selection=1) OR (evidence_role='worker_result' AND role_rank=6 AND ordinal=0 AND required_for_selection=1) OR (evidence_role='validation_result' AND role_rank=7 AND ordinal=0 AND required_for_selection=1) OR (evidence_role='independent_review' AND role_rank=8 AND ordinal=0 AND required_for_selection=1) OR (evidence_role='standing_policy' AND role_rank=9 AND ordinal=0 AND required_for_selection=1) OR (evidence_role='risk_lane' AND role_rank=10 AND ordinal=0 AND required_for_selection=1) OR (evidence_role='authority_currentness_attestation' AND role_rank=11 AND ordinal=0 AND required_for_selection=1) OR (evidence_role='global_stop' AND role_rank=12 AND ordinal=0 AND required_for_selection=1) OR (evidence_role='effect_ceiling' AND role_rank=13 AND ordinal=0 AND required_for_selection=1)))),
  PRIMARY KEY(proposal_ref,evidence_role,ordinal),
  UNIQUE(proposal_ref,role_rank,ordinal),
  FOREIGN KEY(proposal_phase,proposal_ref) REFERENCES development_model_proposals(proposal_phase,proposal_ref) ON UPDATE RESTRICT ON DELETE RESTRICT NOT DEFERRABLE INITIALLY IMMEDIATE
) STRICT;

