  "command_schema_id" ANY NOT NULL CHECK(typeof("command_schema_id")='text' AND length(CAST("command_schema_id" AS BLOB))=length("command_schema_id") AND "command_schema_id"='governed-execution.nwp-record-pre-execution-plan-disposition-command.v1'),
