  "program_ref" ANY NOT NULL CHECK(typeof("program_ref")='text' AND length(CAST("program_ref" AS BLOB))=length("program_ref") AND length(CAST("program_ref" AS BLOB)) BETWEEN 1 AND 96 AND "program_ref" NOT GLOB '*[^0-9A-Za-z.-]*' AND substr("program_ref",1,1) GLOB '[0-9A-Za-z]' AND lower("program_ref") NOT GLOB 'connector-*' AND lower("program_ref") NOT GLOB 'tunnel-*' AND lower("program_ref") NOT GLOB 'workspace-*' AND lower("program_ref") NOT GLOB 'org-*' AND lower("program_ref") NOT GLOB 'organization-*' AND lower("program_ref") NOT GLOB 'user-*'),
  "proposal_ref" ANY NOT NULL CHECK(typeof("proposal_ref")='text' AND length(CAST("proposal_ref" AS BLOB))=length("proposal_ref") AND length(CAST("proposal_ref" AS BLOB)) BETWEEN 1 AND 96 AND "proposal_ref" NOT GLOB '*[^0-9A-Za-z.-]*' AND substr("proposal_ref",1,1) GLOB '[0-9A-Za-z]' AND lower("proposal_ref") NOT GLOB 'connector-*' AND lower("proposal_ref") NOT GLOB 'tunnel-*' AND lower("proposal_ref") NOT GLOB 'workspace-*' AND lower("proposal_ref") NOT GLOB 'org-*' AND lower("proposal_ref") NOT GLOB 'organization-*' AND lower("proposal_ref") NOT GLOB 'user-*'),
  "disposition_ref" ANY NOT NULL CHECK(typeof("disposition_ref")='text' AND length(CAST("disposition_ref" AS BLOB))=length("disposition_ref") AND length(CAST("disposition_ref" AS BLOB)) BETWEEN 1 AND 96 AND "disposition_ref" NOT GLOB '*[^0-9A-Za-z.-]*' AND substr("disposition_ref",1,1) GLOB '[0-9A-Za-z]' AND lower("disposition_ref") NOT GLOB 'connector-*' AND lower("disposition_ref") NOT GLOB 'tunnel-*' AND lower("disposition_ref") NOT GLOB 'workspace-*' AND lower("disposition_ref") NOT GLOB 'org-*' AND lower("disposition_ref") NOT GLOB 'organization-*' AND lower("disposition_ref") NOT GLOB 'user-*'),
  "disposition_digest" ANY NOT NULL CHECK(typeof("disposition_digest")='text' AND length(CAST("disposition_digest" AS BLOB))=length("disposition_digest") AND length(CAST("disposition_digest" AS BLOB))=64 AND "disposition_digest" NOT GLOB '*[^0-9a-f]*'),
  "authority_selection_observation_ref" ANY NOT NULL CHECK(typeof("authority_selection_observation_ref")='text' AND length(CAST("authority_selection_observation_ref" AS BLOB))=length("authority_selection_observation_ref") AND length(CAST("authority_selection_observation_ref" AS BLOB)) BETWEEN 1 AND 96 AND "authority_selection_observation_ref" NOT GLOB '*[^0-9A-Za-z.-]*' AND substr("authority_selection_observation_ref",1,1) GLOB '[0-9A-Za-z]' AND lower("authority_selection_observation_ref") NOT GLOB 'connector-*' AND lower("authority_selection_observation_ref") NOT GLOB 'tunnel-*' AND lower("authority_selection_observation_ref") NOT GLOB 'workspace-*' AND lower("authority_selection_observation_ref") NOT GLOB 'org-*' AND lower("authority_selection_observation_ref") NOT GLOB 'organization-*' AND lower("authority_selection_observation_ref") NOT GLOB 'user-*'),
  "authority_selection_observation_digest" ANY NOT NULL CHECK(typeof("authority_selection_observation_digest")='text' AND length(CAST("authority_selection_observation_digest" AS BLOB))=length("authority_selection_observation_digest") AND length(CAST("authority_selection_observation_digest" AS BLOB))=64 AND "authority_selection_observation_digest" NOT GLOB '*[^0-9a-f]*'),
  "effect_intent_ref" ANY NOT NULL CHECK(typeof("effect_intent_ref")='text' AND length(CAST("effect_intent_ref" AS BLOB))=length("effect_intent_ref") AND length(CAST("effect_intent_ref" AS BLOB)) BETWEEN 1 AND 96 AND "effect_intent_ref" NOT GLOB '*[^0-9A-Za-z.-]*' AND substr("effect_intent_ref",1,1) GLOB '[0-9A-Za-z]' AND lower("effect_intent_ref") NOT GLOB 'connector-*' AND lower("effect_intent_ref") NOT GLOB 'tunnel-*' AND lower("effect_intent_ref") NOT GLOB 'workspace-*' AND lower("effect_intent_ref") NOT GLOB 'org-*' AND lower("effect_intent_ref") NOT GLOB 'organization-*' AND lower("effect_intent_ref") NOT GLOB 'user-*'),
  "selection_head_revision" ANY NOT NULL CHECK(typeof("selection_head_revision")='integer' AND "selection_head_revision" BETWEEN 0 AND 9223372036854775807),
  "selection_head_digest" ANY NOT NULL CHECK(typeof("selection_head_digest")='text' AND length(CAST("selection_head_digest" AS BLOB))=length("selection_head_digest") AND length(CAST("selection_head_digest" AS BLOB))=64 AND "selection_head_digest" NOT GLOB '*[^0-9a-f]*'),
  "result_class" ANY NOT NULL CHECK(typeof("result_class")='text' AND length(CAST("result_class" AS BLOB))=length("result_class") AND "result_class"='pre_execution_plan_disposition_recorded'),
  "result_projection_digest" ANY NOT NULL CHECK(typeof("result_projection_digest")='text' AND length(CAST("result_projection_digest" AS BLOB))=length("result_projection_digest") AND length(CAST("result_projection_digest" AS BLOB))=64 AND "result_projection_digest" NOT GLOB '*[^0-9a-f]*'),
  "mutation_graph_digest" ANY NOT NULL CHECK(typeof("mutation_graph_digest")='text' AND length(CAST("mutation_graph_digest" AS BLOB))=length("mutation_graph_digest") AND length(CAST("mutation_graph_digest" AS BLOB))=64 AND "mutation_graph_digest" NOT GLOB '*[^0-9a-f]*'),
  "outcome" ANY NOT NULL CHECK(typeof("outcome")='text' AND length(CAST("outcome" AS BLOB))=length("outcome") AND "outcome"='committed'),
  "committed_at" ANY NOT NULL CHECK(typeof("committed_at")='text' AND length(CAST("committed_at" AS BLOB))=length("committed_at") AND length(CAST("committed_at" AS BLOB))=20 AND "committed_at" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9]Z' AND substr("committed_at",1,4) BETWEEN '0001' AND '9999' AND substr("committed_at",6,2) BETWEEN '01' AND '12' AND substr("committed_at",9,2) BETWEEN '01' AND '31' AND substr("committed_at",12,2) BETWEEN '00' AND '23' AND substr("committed_at",15,2) BETWEEN '00' AND '59' AND substr("committed_at",18,2) BETWEEN '00' AND '59' AND strftime('%Y-%m-%dT%H:%M:%SZ',"committed_at") IS NOT NULL AND strftime('%Y-%m-%dT%H:%M:%SZ',"committed_at")="committed_at"),
  "receipt_digest" ANY NOT NULL CHECK(typeof("receipt_digest")='text' AND length(CAST("receipt_digest" AS BLOB))=length("receipt_digest") AND length(CAST("receipt_digest" AS BLOB))=64 AND "receipt_digest" NOT GLOB '*[^0-9a-f]*'),
  PRIMARY KEY(mutation_ref),
  UNIQUE(program_ref,mutation_ref),
  UNIQUE(disposition_ref),
  FOREIGN KEY(proposal_ref) REFERENCES development_model_proposals(proposal_ref) ON UPDATE RESTRICT ON DELETE RESTRICT NOT DEFERRABLE INITIALLY IMMEDIATE,
  FOREIGN KEY(program_ref,disposition_ref,proposal_ref,effect_intent_ref,selection_head_revision,selection_head_digest) REFERENCES development_pre_execution_dispositions(program_ref,disposition_ref,proposal_ref,effect_intent_ref,resulting_selection_head_revision,selection_head_postimage_digest) ON UPDATE RESTRICT ON DELETE RESTRICT NOT DEFERRABLE INITIALLY IMMEDIATE,
  FOREIGN KEY(program_ref,effect_intent_ref) REFERENCES development_pre_execution_selection_heads(program_ref,effect_intent_ref) ON UPDATE RESTRICT ON DELETE RESTRICT NOT DEFERRABLE INITIALLY IMMEDIATE
) STRICT;

